sources={'model/nebula.py': '"""Nebula\'s small, randomly initialized causal Transformer. No pretrained weights."""\nimport json\nfrom dataclasses import asdict, dataclass\nfrom pathlib import Path\nimport torch\nfrom torch import nn\n\nBOS, EOS, SYSTEM, USER, ASSISTANT, PAD = range(256, 262)\nVOCAB = 262\nROLES = {"system": SYSTEM, "user": USER, "assistant": ASSISTANT}\n\n@dataclass\nclass Config:\n    width: int = 128\n    heads: int = 4\n    layers: int = 2\n    context: int = 512\n\ndef config_for_preset(preset):\n    presets = {\n        \'smoke\': Config(width=64,heads=2,layers=1,context=256),\n        \'cpu\': Config(),\n        \'cpu-medium\': Config(width=192,heads=6,layers=4,context=1024),\n        \'cpu-large\': Config(width=256,heads=8,layers=6,context=1024),\n        \'gpu\': Config(width=384,heads=8,layers=6,context=2048),\n    }\n    if preset not in presets: raise ValueError(\'Unknown model preset\')\n    return presets[preset]\n\ndef encode(messages, answer_prefix=False):\n    tokens, learn = [BOS], [False]\n    for message in messages:\n        role = message["role"]\n        tokens.append(ROLES[role]); learn.append(False)\n        content = list(message["content"].encode("utf-8"))\n        tokens.extend(content); learn.extend([role == "assistant"] * len(content))\n        tokens.append(EOS); learn.append(role == "assistant")\n    if answer_prefix:\n        tokens.append(ASSISTANT); learn.append(False)\n    return tokens, learn\n\ndef pack_prompt(messages, context):\n    systems = [m for m in messages if m[\'role\'] == \'system\']\n    history = [m for m in messages if m[\'role\'] != \'system\']\n    if not history or history[-1][\'role\'] != \'user\': raise ValueError(\'A user question is required\')\n    prefix, _ = encode(systems)\n    selected = []\n    # Keep every system instruction and the full latest question; never silently cut rules.\n    available = context - len(prefix) - 2\n    for message in reversed(history):\n        chunk = encode([message])[0][1:]\n        if len(chunk) > available:\n            if not selected: raise ValueError(\'Rules and question exceed the model context\')\n            break\n        selected.insert(0, chunk); available -= len(chunk)\n    return prefix + [token for chunk in selected for token in chunk] + [ASSISTANT]\n\nclass Nebula(nn.Module):\n    def __init__(self, config):\n        super().__init__(); self.config = config\n        self.token = nn.Embedding(VOCAB, config.width)\n        self.position = nn.Embedding(config.context, config.width)\n        self.blocks = nn.ModuleList(nn.TransformerEncoderLayer(config.width, config.heads, config.width * 4, dropout=0.0, activation="gelu", batch_first=True, norm_first=True) for _ in range(config.layers))\n        self.norm = nn.LayerNorm(config.width)\n        self.output = nn.Linear(config.width, VOCAB, bias=False)\n        self.output.weight = self.token.weight\n        self.register_buffer(\'_causal_mask\',torch.ones(config.context,config.context,dtype=torch.bool).triu(1),persistent=False)\n        self.apply(self._initialize)\n\n    @staticmethod\n    def _initialize(module):\n        if isinstance(module, (nn.Linear, nn.Embedding)):\n            nn.init.normal_(module.weight, std=0.02)\n            if isinstance(module, nn.Linear) and module.bias is not None: nn.init.zeros_(module.bias)\n\n    def forward(self, tokens):\n        length = tokens.shape[1]\n        if length > self.config.context: raise ValueError("Context is too long")\n        value = self.token(tokens) + self.position(torch.arange(length, device=tokens.device))\n        causal = self._causal_mask[:length,:length]\n        for block in self.blocks: value = block(value, src_mask=causal)\n        return self.output(self.norm(value))\n\n    @torch.inference_mode()\n    def reply(self, messages, max_tokens=160, temperature=0.7):\n        self.eval()\n        encoded = pack_prompt(messages, self.config.context)\n        device = next(self.parameters()).device\n        tokens = torch.tensor([encoded], device=device)\n        result = []\n        for _ in range(min(max_tokens, self.config.context - len(encoded))):\n            logits = self(tokens)[:, -1, :].clone()\n            end = logits[:, EOS].clone(); logits[:, BOS:] = float(\'-inf\'); logits[:, EOS] = end\n            if temperature == 0: next_token = logits.argmax(-1, keepdim=True)\n            else: next_token = torch.multinomial(torch.softmax(logits / temperature, -1), 1)\n            value = int(next_token.item())\n            if value == EOS: break\n            result.append(value); tokens = torch.cat([tokens, next_token], dim=1)\n        return bytes(result).decode(\'utf-8\', errors=\'replace\').strip()\n\ndef save(model, path, metadata):\n    if any(not torch.isfinite(parameter).all() for parameter in model.parameters()):\n        raise ValueError(\'Checkpoint contains non-finite weights; existing saved weights were not replaced\')\n    path = Path(path); path.parent.mkdir(parents=True, exist_ok=True)\n    temporary = path.with_suffix(\'.tmp\')\n    torch.save({\'format\': 1, \'config\': asdict(model.config), \'state\': model.state_dict(), \'metadata\': metadata}, temporary)\n    temporary.replace(path)\n\ndef load(path):\n    data = torch.load(path, map_location=\'cpu\', weights_only=True)\n    if data.get(\'format\') != 1: raise ValueError(\'Unsupported model checkpoint\')\n    model = Nebula(Config(**data[\'config\'])); model.load_state_dict(data[\'state\']); model.eval()\n    if any(not torch.isfinite(parameter).all() for parameter in model.parameters()):\n        raise ValueError(\'Checkpoint contains non-finite weights; resume from a healthy best checkpoint\')\n    return model, data.get(\'metadata\', {})\n', 'model/train.py': 'import argparse\nimport hashlib\nimport json\nimport random\nimport time\nimport itertools\nimport math\nfrom contextlib import nullcontext\nfrom pathlib import Path\nimport torch\nfrom torch.nn import functional as F\nfrom nebula import Config, Nebula, PAD, encode, load, save, config_for_preset\nfrom dataflow import read_jsonl, eligible\nfrom rules import with_owner_rules\n\nclass NumericalFailure(RuntimeError): pass\n\ndef examples(rows, context, include_owner_rules=False, objective=\'assistant\'):\n    result = []\n    for row in rows:\n        messages = row[\'messages\']\n        if objective == \'language\':\n            # Language pretraining uses continuous serialized text chunks, with no\n            # invented end-of-answer tokens at chunk boundaries. Chat tuning below\n            # uses complete replies instead.\n            prefix=encode(with_owner_rules([]) if include_owner_rules else [])[0]\n            body=encode(messages)[0][1:]\n            room=context+1-len(prefix)\n            if room<1: raise ValueError(\'Owner rules exceed model context\')\n            for offset in range(0,len(body),room):\n                tokens=prefix+body[offset:offset+room]\n                x=torch.tensor(tokens[:-1]); y=torch.tensor([-100]*(len(prefix)-1)+tokens[len(prefix):])\n                result.append((x,y))\n            continue\n        wrapped = with_owner_rules(messages) if include_owner_rules else messages\n        windows = [wrapped]\n        if len(encode(wrapped)[0]) > context + 1:\n            windows = []\n            for end in range(2,len(messages)+1,2):\n                for start in range(0,end,2):\n                    candidate=with_owner_rules(messages[start:end]) if include_owner_rules else messages[start:end]\n                    if len(encode(candidate)[0]) <= context+1:\n                        windows.append(candidate); break\n        for window in windows:\n            tokens, learn = encode(window)\n            x = torch.tensor(tokens[:-1]); y = torch.tensor([v if mask else -100 for v, mask in zip(tokens[1:], learn[1:])])\n            if (y != -100).any(): result.append((x, y))\n    return result\n\ndef partition_rows(rows, seed):\n    """Split original dialogues before creating windows, keeping duplicates together."""\n    training=[]; validation=[]\n    for row in rows:\n        identifier=hashlib.sha256(json.dumps(row[\'messages\'],sort_keys=True).encode()).hexdigest()\n        score=int(hashlib.sha256((str(seed)+\':\'+identifier).encode()).hexdigest()[:8],16)\n        (validation if score%10==0 else training).append(row)\n    if not training or not validation: raise ValueError(\'Grouped split requires enough distinct conversations\')\n    return training,validation\n\ndef bucket_batches(data,batch_size,rng):\n    ordered=sorted(data,key=lambda pair:len(pair[0])); batches=[]\n    for offset in range(0,len(ordered),max(batch_size*32,32)):\n        bucket=ordered[offset:offset+max(batch_size*32,32)]; rng.shuffle(bucket)\n        batches.extend(bucket[i:i+batch_size] for i in range(0,len(bucket),batch_size))\n    rng.shuffle(batches)\n    return batches\n\ndef unique_windows(data,excluded=None):\n    seen=set(excluded or []); result=[]\n    for x,y in data:\n        identifier=hashlib.sha256(x.numpy().tobytes()+y.numpy().tobytes()).hexdigest()\n        if identifier in seen: continue\n        seen.add(identifier); result.append((x,y))\n    return result,seen\n\ndef loss(model, batch):\n    length = max(len(x) for x, _ in batch)\n    x = torch.full((len(batch), length), PAD, dtype=torch.long); y = torch.full_like(x, -100)\n    for i, (a, b) in enumerate(batch): x[i, :len(a)] = a; y[i, :len(b)] = b\n    device=next(model.parameters()).device\n    autocast=torch.autocast(\'cuda\',dtype=model._amp_dtype) if getattr(model,\'_amp_enabled\',False) else nullcontext()\n    with autocast:\n        return F.cross_entropy(model(x.to(device)).reshape(-1, 262), y.to(device).reshape(-1), ignore_index=-100)\n\ndef evaluate_loss(model, data, batch_size):\n    total = tokens = 0\n    for offset in range(0, len(data), batch_size):\n        batch = data[offset:offset+batch_size]\n        count = sum(int((y != -100).sum()) for _, y in batch)\n        total += float(loss(model, batch)) * count; tokens += count\n    return total / tokens if tokens else None\n\ndef train(args):\n    if args.steps < 1 or args.batch < 1 or args.threads < 1: raise ValueError(\'Positive steps, batch and threads required\')\n    if not math.isfinite(args.lr) or args.lr <= 0: raise ValueError(\'Learning rate must be finite and positive\')\n    continuous = getattr(args, \'continuous\', False)\n    save_every = getattr(args, \'save_every\', 100)\n    patience = getattr(args, \'patience\', 0)\n    if patience < 0: raise ValueError(\'Patience must be zero or positive\')\n    if save_every < 1: raise ValueError(\'Save interval must be positive\')\n    torch.set_num_threads(args.threads); torch.manual_seed(args.seed); rng = random.Random(args.seed)\n    rows = read_jsonl(args.data)\n    snapshot = json.loads(Path(args.snapshot).read_text(encoding=\'utf-8\')) if args.snapshot else None\n    if any(row.get(\'source\', {}).get(\'kind\') == \'user\' for row in rows):\n        if continuous: raise ValueError(\'Continuous runs require seed/teacher data; user consent must be refreshed between bounded runs\')\n        if not snapshot or not 0 <= time.time() * 1000 - snapshot.get(\'createdAt\', 0) < 300000:\n            raise ValueError(\'User examples require a fresh consent check. Use scripts/model-data.mjs train.\')\n    # User records always require a fresh Firebase consent snapshot supplied by the wrapper.\n    rows = [row for row in rows if eligible(row, snapshot)]\n    if args.resume: model,resume_metadata=load(args.resume)\n    else: model,resume_metadata=Nebula(config_for_preset(args.preset)),{}\n    inherited_steps=resume_metadata.get(\'steps\',0)\n    requested_device=getattr(args,\'device\',\'cpu\')\n    device=\'cuda\' if requested_device==\'auto\' and torch.cuda.is_available() else \'cpu\' if requested_device==\'auto\' else requested_device\n    if device==\'cuda\' and not torch.cuda.is_available(): raise ValueError(\'CUDA GPU is unavailable in this PyTorch installation\')\n    model.to(device)\n    model._amp_enabled=device==\'cuda\' and getattr(args,\'amp\',False)\n    model._amp_dtype=torch.bfloat16 if device==\'cuda\' and torch.cuda.is_bf16_supported() else torch.float16\n    scaler=torch.amp.GradScaler(\'cuda\',enabled=model._amp_enabled and model._amp_dtype==torch.float16)\n    objective=getattr(args,\'objective\',\'assistant\')\n    grouped=getattr(args,\'grouped_split\',False)\n    if grouped:\n        train_rows,validation_rows=partition_rows(rows,args.seed)\n        training=examples(train_rows,model.config.context,True,objective)\n        validation=examples(validation_rows,model.config.context,True,objective)\n        training,seen_windows=unique_windows(training)\n        validation,_=unique_windows(validation,seen_windows)\n        data=training+validation\n    else:\n        data = examples(rows, model.config.context, include_owner_rules=True,objective=objective)\n        rng.shuffle(data); split = max(1, int(len(data) * .9)); training, validation = data[:split], data[split:]\n    if not training: raise ValueError(\'No approved training examples fit the model context\')\n    if grouped and not validation: raise ValueError(\'No validation conversations fit the model context\')\n    available_validation=len(validation)\n    max_validation=getattr(args,\'max_validation\',0)\n    if max_validation:\n        validation_rng=random.Random(args.seed+1)\n        validation=validation_rng.sample(validation,min(len(validation),max_validation))\n    validation.sort(key=lambda pair:len(pair[0]))\n    optimizer = torch.optim.AdamW(model.parameters(), lr=args.lr, weight_decay=.01)\n    with torch.no_grad(): initial = float(loss(model, training[:args.batch]))\n    if not math.isfinite(initial): initial=None\n    completed = 0\n    data_hash = hashlib.sha256(Path(args.data).read_bytes()).hexdigest()\n    best_path = Path(args.output).with_suffix(\'.best.pt\')\n    best_validation = float(\'inf\')\n    stale_checks = 0\n    if best_path.exists():\n        _, previous = load(best_path)\n        if previous.get(\'dataSha256\') == data_hash and previous.get(\'seed\') == args.seed and previous.get(\'objective\',\'assistant\') == objective and previous.get(\'groupedSplit\',False) == grouped and previous.get(\'maxValidation\',0) == max_validation and previous.get(\'windowFormat\',1)==2:\n            previous_loss = previous.get(\'validationLoss\')\n            if isinstance(previous_loss, (int, float)): best_validation = previous_loss\n    def checkpoint(stopped=False,validate=True,reason=None):\n        nonlocal best_validation, stale_checks\n        model.eval()\n        current=validation_loss=None\n        if validate:\n            with torch.no_grad():\n                current = float(loss(model, training[:args.batch]))\n                validation_loss = evaluate_loss(model, validation, args.batch)\n            if not math.isfinite(current) or validation_loss is not None and not math.isfinite(validation_loss):\n                raise NumericalFailure(\'Non-finite checkpoint metric\')\n        report = {\'parameters\': sum(p.numel() for p in model.parameters()), \'steps\': inherited_steps+completed,\'stepsThisRun\':completed, \'trainingExamples\': len(training), \'validationExamples\': len(validation),\'availableValidationExamples\':available_validation,\'originalConversations\':len(rows), \'skippedExamples\': None if grouped else max(0,len(rows) - len(data)), \'initialLoss\': initial, \'finalLoss\': current, \'validationLoss\': validation_loss, \'seed\': args.seed, \'dataSha256\': data_hash, \'experimental\': True, \'qualityApproved\': False, \'stopped\': stopped,\'objective\':objective,\'groupedSplit\':grouped,\'maxValidation\':max_validation,\'device\':device,\'windowFormat\':2}\n        if reason: report[\'stopReason\']=reason\n        save(model, args.output, report)\n        if validation_loss is not None and validation_loss < best_validation:\n            best_validation = validation_loss\n            stale_checks = 0\n            save(model, best_path, report)\n            print(json.dumps({\'bestCheckpoint\': str(best_path), \'validationLoss\': best_validation}), flush=True)\n        elif validation_loss is not None:\n            stale_checks += 1\n            if validation_loss > best_validation * 1.2:\n                print(\'Validation loss is worsening: this run is overfitting. More varied data is needed; Ctrl+C saves and stops.\', flush=True)\n        print(json.dumps({\'checkpoint\': str(args.output), **report}), flush=True)\n    # Save even before the first update, then periodically and on Ctrl+C.\n    batches=[]; epoch=0; started=time.monotonic(); trained_tokens=0\n    try:\n        checkpoint()\n        for step in itertools.count() if continuous else range(args.steps):\n            if getattr(args,\'bucketed\',False):\n                if not batches: batches=bucket_batches(training,args.batch,rng); epoch+=1\n                batch=batches.pop()\n            else: batch = [training[rng.randrange(len(training))] for _ in range(args.batch)]\n            model.train()\n            optimizer.zero_grad(set_to_none=True); value = loss(model, batch)\n            if not torch.isfinite(value): raise NumericalFailure(\'Non-finite training loss\')\n            scaler.scale(value).backward(); scaler.unscale_(optimizer)\n            gradient_norm=torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)\n            if not torch.isfinite(gradient_norm): raise NumericalFailure(\'Non-finite gradients; optimizer update was blocked\')\n            scaler.step(optimizer); scaler.update()\n            completed = step + 1\n            trained_tokens+=sum(len(x) for x,_ in batch)\n            if step == 0 or completed % 25 == 0: print(json.dumps({\'step\': completed, \'loss\': round(float(value.detach()), 4),\'epoch\':epoch or None,\'tokensPerSecond\':round(trained_tokens/max(.001,time.monotonic()-started))}), flush=True)\n            if completed % save_every == 0:\n                checkpoint()\n                if patience and stale_checks >= patience:\n                    print(json.dumps({\'stopped\':\'validation_not_improving\',\'steps\':completed,\'bestCheckpoint\':str(best_path),\'note\':\'Latest weights and best validation weights are saved. Live website unchanged.\'}),flush=True)\n                    return {\'steps\':completed,\'stopped\':True,\'reason\':\'validation_not_improving\'}\n    except KeyboardInterrupt:\n        checkpoint(stopped=True,validate=False,reason=\'interrupted\')\n        print(\'Stopped. Latest weights saved; the live website was not changed.\', flush=True)\n        return {\'steps\': completed, \'stopped\': True}\n    except NumericalFailure:\n        optimizer.zero_grad(set_to_none=True)\n        try:\n            checkpoint(stopped=True,validate=False,reason=\'non_finite_loss_or_gradient\')\n            message=\'Stopped for a numerical error. Finite current weights saved without validation; the best checkpoint is preserved.\'\n        except ValueError:\n            message=\'Stopped for a numerical error. Invalid weights were not saved; existing checkpoints are preserved.\'\n        print(message+\' Resume from a healthy best checkpoint with a lower learning rate.\',flush=True)\n        return {\'steps\':completed,\'stopped\':True,\'reason\':\'non_finite_loss_or_gradient\'}\n    checkpoint()\n    report=load(args.output)[1]\n    return report\n\nif __name__ == \'__main__\':\n    parser = argparse.ArgumentParser(description=\'Train owned Nebula weights from scratch. CPU preset is experimental, not production quality.\')\n    parser.add_argument(\'--continuous\', action=\'store_true\'); parser.add_argument(\'--save-every\', type=int, default=100)\n    parser.add_argument(\'--patience\', type=int, default=0, help=\'Stop after this many validation checks without improvement; 0 disables\')\n    parser.add_argument(\'--device\',choices=[\'auto\',\'cpu\',\'cuda\'],default=\'auto\')\n    parser.add_argument(\'--objective\',choices=[\'assistant\',\'language\'],default=\'assistant\')\n    parser.add_argument(\'--grouped-split\',action=\'store_true\'); parser.add_argument(\'--bucketed\',action=\'store_true\'); parser.add_argument(\'--max-validation\',type=int,default=0)\n    parser.add_argument(\'--data\', required=True); parser.add_argument(\'--output\', required=True); parser.add_argument(\'--snapshot\'); parser.add_argument(\'--resume\'); parser.add_argument(\'--preset\', choices=[\'cpu\', \'smoke\',\'cpu-medium\',\'cpu-large\',\'gpu\'], default=\'cpu\'); parser.add_argument(\'--steps\', type=int, default=500); parser.add_argument(\'--batch\', type=int, default=4); parser.add_argument(\'--threads\', type=int, default=2); parser.add_argument(\'--seed\', type=int, default=42); parser.add_argument(\'--lr\', type=float, default=.0005)\n    train(parser.parse_args())\n', 'model/dataflow.py': '"""Reviewed datasets. These commands never call teachers with user chat content."""\nimport hashlib\nimport json\nimport re\nfrom pathlib import Path\nfrom urllib.request import Request, urlopen\nfrom urllib.parse import urlparse\nimport os\nimport time\nfrom teacher_http import request_json\nfrom rules import owner_instructions\n\ndef read_jsonl(path):\n    with Path(path).open(encoding=\'utf-8\') as stream:\n        return [json.loads(line) for line in stream if line.strip()]\n\ndef write_jsonl(path, rows):\n    path = Path(path); path.parent.mkdir(parents=True, exist_ok=True)\n    temporary = path.with_suffix(\'.tmp\')\n    temporary.write_text(\'\'.join(json.dumps(row, ensure_ascii=False) + \'\\n\' for row in rows), encoding=\'utf-8\')\n    temporary.replace(path)\n\ndef redact(text):\n    text = re.sub(r\'\\b[\\w.+-]+@[\\w.-]+\\.[a-zA-Z]{2,}\\b\', \'[email removed]\', text)\n    text = re.sub(r\'\\b(?:sk-|AIza)[\\w-]{15,}\\b\', \'[credential removed]\', text)\n    text = re.sub(r\'\\bBearer\\s+[\\w.~/+=-]{12,}\', \'[credential removed]\', text, flags=re.I)\n    text = re.sub(r\'(?<!\\w)(?:\\+?\\d[\\d ()-]{7,}\\d)(?!\\w)\', \'[number removed]\', text)\n    return text\n\ndef example_id(messages):\n    return hashlib.sha256(json.dumps(messages, sort_keys=True).encode()).hexdigest()\n\ndef eligible(row, snapshot=None):\n    if row.get(\'reviewStatus\') != \'approved\': return False\n    source = row.get(\'source\', {})\n    if source.get(\'kind\') == \'user\':\n        if not snapshot: return False\n        profile = snapshot.get(\'accounts\', {}).get(source.get(\'accountKey\'))\n        owner = snapshot.get(\'training\', {}).get(source.get(\'owner\'))\n        if not profile or profile.get(\'improve\') is not True or not owner or owner.get(\'revoked\'): return False\n        if profile.get(\'trainingGeneration\', 0) != source.get(\'generation\'): return False\n        original = owner.get(\'samples\', {}).get(source.get(\'chatId\'), {}).get(source.get(\'turnId\'))\n        if not original or original.get(\'consentVersion\') != 1: return False\n        # An export cannot be modified into different content while claiming old consent.\n        messages = [{\'role\': m[\'role\'], \'content\': redact(m[\'content\'])} for m in original.get(\'messages\', [])]\n        # Reviewers may correct the answer, but cannot replace the consented user prompt.\n        if not messages or not row.get(\'messages\') or row[\'messages\'][0] != messages[0]: return False\n    elif source.get(\'kind\') == \'teacher\':\n        if source.get(\'trainingAllowed\') is not True: return False\n    elif source.get(\'kind\') == \'public\':\n        allowed = (source.get(\'dataset\') == \'HuggingFaceTB/everyday-conversations-llama3.1-2k\' and source.get(\'subset\') == \'default\') or (source.get(\'dataset\') == \'HuggingFaceTB/smoltalk\' and source.get(\'subset\') == \'smol-magpie-ultra\')\n        if not allowed or source.get(\'license\') != \'apache-2.0\' or not source.get(\'recordId\'): return False\n    elif source.get(\'kind\') != \'seed\': return False\n    messages = row.get(\'messages\')\n    # User exports remain a single consent-checked pair. Owned/teacher datasets may be dialogues.\n    maximum = 2 if source.get(\'kind\') == \'user\' else 12\n    return (isinstance(messages, list) and 2 <= len(messages) <= maximum and len(messages) % 2 == 0\n            and all(isinstance(m, dict) and m.get(\'role\') == (\'user\' if i % 2 == 0 else \'assistant\')\n                    and isinstance(m.get(\'content\'), str) and 0 < len(m[\'content\'].strip()) <= 16000\n                    for i, m in enumerate(messages)))\n\ndef prepare(inputs, output, snapshot=None):\n    rows, seen = [], set()\n    for path in inputs:\n        for row in read_jsonl(path):\n            if not eligible(row, snapshot): continue\n            identifier = example_id(row[\'messages\'])\n            if identifier in seen: continue\n            seen.add(identifier); rows.append({**row, \'id\': identifier})\n    if not rows: raise ValueError(\'No approved, currently eligible training examples\')\n    write_jsonl(output, rows)\n    return len(rows)\n\ndef generate_teacher(config, prompts, output, limit=10, transport=None):\n    """Bounded calls to an OpenAI-compatible API. Original prompts only."""\n    if not 1 <= limit <= 100: raise ValueError(\'Request limit must be 1 to 100\')\n    if config.get(\'trainingAllowed\') is not True: raise ValueError(\'Choose a teacher whose output may be used for training\')\n    endpoint = config[\'url\']; parsed = urlparse(endpoint)\n    if parsed.username or parsed.password or parsed.query: raise ValueError(\'Credentials belong in an environment variable\')\n    if parsed.scheme != \'https\' and not (parsed.scheme == \'http\' and parsed.hostname in [\'localhost\', \'127.0.0.1\', \'::1\']): raise ValueError(\'HTTPS required for remote teacher\')\n    key = os.environ.get(config.get(\'keyEnv\', \'NEBULA_TEACHER_KEY\'), \'\')\n    if not key and parsed.hostname not in [\'localhost\', \'127.0.0.1\', \'::1\']: raise ValueError(\'Teacher API key is missing\')\n    rows = read_jsonl(output) if Path(output).exists() else []\n    completed = {r.get(\'promptId\') for r in rows}\n    calls = 0\n    for prompt in prompts:\n        # Prevent accidental transmission of exported user conversations to teachers.\n        if prompt.get(\'source\') != \'original\' or not isinstance(prompt.get(\'prompt\'), str): raise ValueError(\'Teacher prompts must be original curriculum prompts\')\n        text = prompt[\'prompt\'].strip()\n        if not text or len(text) > 4000: raise ValueError(\'Invalid curriculum prompt\')\n        identifier = hashlib.sha256((config.get(\'name\', \'custom\') + \':\' + config[\'model\'] + \':\' + text).encode()).hexdigest()\n        if identifier in completed: continue\n        if calls >= limit: break\n        payload = {\'model\': config[\'model\'], \'messages\': [{\'role\': \'system\', \'content\': \'Create a training example for Nebula using these owner instructions.\\n\' + owner_instructions() + \'\\n\' + config.get(\'instructions\', \'\')}, {\'role\': \'user\', \'content\': text}], \'max_tokens\': min(int(config.get(\'maxTokens\', 256)), 1024), \'temperature\': 0.6}\n        if config.get(\'temperature\', 0.6) is None: payload.pop(\'temperature\')\n        if config.get(\'reasoningEffort\') in [\'low\',\'medium\',\'high\']: payload[\'reasoning_effort\'] = config[\'reasoningEffort\']\n        request = Request(endpoint, json.dumps(payload).encode(), {\'Content-Type\': \'application/json\', \'User-Agent\':\'Nebula-Teacher/1.0\', **({\'Authorization\': \'Bearer \' + key} if key else {})})\n        if calls and not transport:\n            delay = min(60, max(0, float(config.get(\'requestIntervalSeconds\', 0))))\n            if delay: time.sleep(delay)\n        if transport: data = transport(request)\n        else:\n            # Never follow a redirect carrying a credential to another host.\n            from urllib.request import build_opener, HTTPRedirectHandler\n            class NoRedirect(HTTPRedirectHandler):\n                def redirect_request(self, *args, **kwargs): return None\n            data = request_json(build_opener(NoRedirect), request, provider=config.get(\'name\',\'teacher\'), max_retries=int(config.get(\'httpRetries\',2)))\n        answer = data[\'choices\'][0][\'message\'][\'content\']\n        if not isinstance(answer, str) or not answer.strip() or len(answer) > 16000: raise ValueError(\'Invalid teacher answer\')\n        rows.append({\'promptId\': identifier, \'reviewStatus\': \'pending\', \'messages\': [{\'role\': \'user\', \'content\': text}, {\'role\': \'assistant\', \'content\': redact(answer)}], \'source\': {\'kind\': \'teacher\', \'provider\': config.get(\'name\', \'custom\'), \'model\': config[\'model\'], \'trainingAllowed\': True}})\n        calls += 1; completed.add(identifier); write_jsonl(output, rows)\n    return calls\n', 'model/teacher_http.py': '"""Bounded HTTP retries and credential-free quota diagnostics."""\nimport json\nimport math\nimport re\nimport time\nfrom urllib.error import HTTPError\n\nclass TeacherRequestError(ValueError):\n    def __init__(self, message, status=429, retry_after=60, retryable=True):\n        super().__init__(message)\n        self.status = status\n        self.retry_after = retry_after\n        self.retryable = retryable\n\ndef quota_info(error):\n    result = {\'zero\': False, \'daily\': False, \'retry\': None}\n    try:\n        raw = error.read(200001)\n        if len(raw) > 200000: return result\n        value = json.loads(raw).get(\'error\', {})\n        message = str(value.get(\'message\', \'\'))\n        result[\'zero\'] = bool(re.search(r\'limit\\s*:\\s*0(?:\\D|$)\', message, re.I))\n        for detail in value.get(\'details\', []):\n            if not isinstance(detail, dict): continue\n            if str(detail.get(\'@type\', \'\')).endswith(\'RetryInfo\'):\n                match = re.fullmatch(r\'(\\d+(?:\\.\\d+)?)s\', str(detail.get(\'retryDelay\', \'\')))\n                if match: result[\'retry\'] = math.ceil(float(match[1]))\n            if str(detail.get(\'@type\', \'\')).endswith(\'QuotaFailure\'):\n                for violation in detail.get(\'violations\', []):\n                    if not isinstance(violation, dict): continue\n                    if str(violation.get(\'quotaValue\', \'\')) == \'0\': result[\'zero\'] = True\n                    if \'perday\' in str(violation.get(\'quotaId\', \'\')).lower(): result[\'daily\'] = True\n        header = error.headers.get(\'Retry-After\') if error.headers else None\n        if header and header.isdigit(): result[\'retry\'] = max(result[\'retry\'] or 0, int(header))\n    except (ValueError, TypeError, AttributeError, OSError): pass\n    return result\n\ndef request_json(opener, request, sleep=time.sleep, provider=\'gemini\', max_retries=2):\n    label = \'Groq\' if provider == \'groq\' else \'Gemini secondary\' if provider == \'gemini-secondary\' else \'Gemini\' if provider == \'gemini\' else \'Teacher\'\n    quota_url = \'https://console.groq.com/settings/limits\' if provider == \'groq\' else \'https://aistudio.google.com/rate-limit\' if provider in [\'gemini\',\'gemini-secondary\'] else \'your provider quota dashboard\'\n    for attempt in range(max_retries + 1):\n        try:\n            with opener.open(request, timeout=60) as response:\n                raw = response.read(200001)\n                if len(raw) > 200000: raise ValueError(\'Teacher reply too large\')\n                return json.loads(raw)\n        except HTTPError as error:\n            if error.code != 429: raise\n            info = quota_info(error)\n            if info[\'zero\']:\n                raise TeacherRequestError(f\'{label} HTTP 429: this model has a zero quota limit for your project. Check {quota_url} and select a model with available quota. Retrying cannot change a zero limit.\', retryable=False) from None\n            if info[\'daily\']:\n                raise TeacherRequestError(f\'{label} HTTP 429: daily quota exhausted. Check {quota_url} for the reset. Completed examples remain saved.\', retryable=False) from None\n            delay = max(15 * (2 ** attempt), info[\'retry\'] or 0)\n            if attempt == max_retries or delay > 60:\n                hint = f\' Provider suggests waiting {info["retry"]} seconds.\' if info[\'retry\'] is not None else \'\'\n                raise TeacherRequestError(f\'{label} HTTP 429: rate or quota limit still blocks requests.\' + hint + f\' Check {quota_url}. Completed examples remain saved.\', retry_after=max(60,info[\'retry\'] or 0)) from None\n            print(f\'{label} rate limited. Waiting {delay} seconds before retry {attempt + 1}/2. Ctrl+C stops.\', flush=True)\n            sleep(delay)\n', 'model/rules.py': '"""Owner instructions shared by training and private inference."""\nimport json\nimport os\nfrom pathlib import Path\n\ndef owner_instructions():\n    value = json.loads((Path(__file__).resolve().parent.parent / \'nebula-rules.json\').read_text(encoding=\'utf-8\'))\n    lines = value.get(\'instructions\')\n    if not isinstance(lines, list) or not lines or any(not isinstance(line, str) or not line.strip() for line in lines): raise ValueError(\'Invalid owner rules\')\n    extra = os.environ.get(\'NEBULA_OWNER_INSTRUCTIONS\', \'\')\n    text = \'\\n\'.join(lines + ([extra] if extra else []))\n    if len(text) > 16000: raise ValueError(\'Owner instructions too long\')\n    return text\n\ndef with_owner_rules(messages):\n    text = owner_instructions()\n    if messages and messages[0][\'role\'] == \'system\' and (messages[0][\'content\'] == text or messages[0][\'content\'].startswith(text + \'\\n\')): return messages\n    return [{\'role\': \'system\', \'content\': text}, *messages]\n', 'model/public_data.py': '"""Download a bounded, cached public training sample; never call teacher APIs."""\nimport argparse\nimport hashlib\nimport json\nfrom pathlib import Path\nimport sys\nimport time\nfrom urllib.parse import urlencode\nfrom urllib.request import Request, urlopen\n\nSOURCES = {\n    \'everyday\': {\'dataset\':\'HuggingFaceTB/everyday-conversations-llama3.1-2k\',\'config\':\'default\',\'split\':\'train_sft\',\'license\':\'apache-2.0\',\'author\':\'Hugging Face\'},\n    \'magpie\': {\'dataset\':\'HuggingFaceTB/smoltalk\',\'config\':\'smol-magpie-ultra\',\'split\':\'train\',\'license\':\'apache-2.0\',\'author\':\'HuggingFaceTB\'},\n}\n\ndef fetch_page(source, offset, length, cache, transport=None):\n    path = cache / f\'{offset}-{length}.json\'\n    if path.exists(): return json.loads(path.read_text(encoding=\'utf-8\'))\n    query = urlencode({k:source[k] for k in [\'dataset\',\'config\',\'split\']} | {\'offset\':offset,\'length\':length})\n    url = \'https://datasets-server.huggingface.co/rows?\' + query\n    if transport: value = transport(url)\n    else:\n        for attempt in range(3):\n            try:\n                with urlopen(Request(url,headers={\'User-Agent\':\'Nebula-Public-Data/1.0\'}),timeout=45) as response:\n                    raw = response.read(12000001)\n                    if len(raw)>12000000: raise ValueError(\'Dataset page too large\')\n                    value = json.loads(raw)\n                break\n            except Exception:\n                if attempt == 2: raise\n                time.sleep(2 ** attempt)\n    if not isinstance(value.get(\'rows\'),list): raise ValueError(\'Invalid dataset page\')\n    cache.mkdir(parents=True,exist_ok=True)\n    temporary=path.with_suffix(\'.tmp\'); temporary.write_text(json.dumps(value),encoding=\'utf-8\'); temporary.replace(path)\n    return value\n\ndef convert(item, source, index):\n    messages = item.get(\'messages\')\n    if not isinstance(messages,list) or not 2<=len(messages)<=12 or len(messages)%2: return None\n    if any(not isinstance(m,dict) or m.get(\'role\')!=(\'user\' if i%2==0 else \'assistant\') or not isinstance(m.get(\'content\'),str) or not m[\'content\'].strip() or len(m[\'content\'])>16000 for i,m in enumerate(messages)): return None\n    # Identity boilerplate from a teacher is unsuitable as Nebula\'s identity training.\n    text=\' \'.join(m[\'content\'].lower() for m in messages if m[\'role\']==\'assistant\')\n    if any(phrase in text for phrase in [\'i am chatgpt\',\'i\\\'m chatgpt\',\'i am llama\',\'i\\\'m llama\',\'i am gemini\',\'i\\\'m gemini\']): return None\n    from dataflow import redact\n    messages=[{\'role\':m[\'role\'],\'content\':redact(m[\'content\'])} for m in messages]\n    identifier=hashlib.sha256(json.dumps(messages,sort_keys=True).encode()).hexdigest()\n    return {\'id\':identifier,\'reviewStatus\':\'approved\',\'approvalMethod\':\'public-dataset-structural-filter-unverified\',\'messages\':messages,\'source\':{\'kind\':\'public\',\'dataset\':source[\'dataset\'],\'subset\':source[\'config\'],\'license\':source[\'license\'],\'recordId\':identifier,\'rowIndex\':index,\'url\':\'https://huggingface.co/datasets/\'+source[\'dataset\']}}\n\ndef download(output, everyday=2260, magpie=5000, transport=None):\n    from dataflow import write_jsonl\n    if not 0<=everyday<=2260 or not 0<=magpie<=20000: raise ValueError(\'Bounded download requires 0-2260 everyday and 0-20000 magpie rows\')\n    output=Path(output); output.mkdir(parents=True,exist_ok=True)\n    rows=[]; seen=set(); counts={}\n    for name,limit in [(\'everyday\',everyday),(\'magpie\',magpie)]:\n        source=SOURCES[name]; offset=0; accepted=0\n        while offset<limit:\n            page=fetch_page(source,offset,min(100,limit-offset),output/\'public-cache\'/name,transport)\n            entries=page[\'rows\']\n            if not entries: break\n            for entry in entries:\n                # Dataset viewer may truncate large cells; never train their partial text.\n                if entry.get(\'truncated_cells\'): continue\n                row=convert(entry.get(\'row\',{}),source,entry.get(\'row_idx\',offset))\n                if row and row[\'id\'] not in seen: seen.add(row[\'id\']); rows.append(row); accepted+=1\n            offset+=len(entries)\n            print(json.dumps({\'publicDataset\':name,\'scanned\':offset,\'accepted\':accepted}),flush=True)\n            if offset>=page.get(\'num_rows_total\',limit): break\n        counts[name]=accepted\n    if not rows: raise ValueError(\'No valid public examples downloaded\')\n    write_jsonl(output/\'public-conversations.jsonl\',rows)\n    manifest={\'sources\':list(SOURCES.values()),\'counts\':counts,\'conversations\':len(rows),\'trainingDataSha256\':hashlib.sha256((output/\'public-conversations.jsonl\').read_bytes()).hexdigest(),\'changes\':[\'Removed malformed, duplicate and truncated records\',\'Redacted likely contact details and credentials\',\'Rejected selected foreign identity boilerplate\'],\'quality\':\'Not individually reviewed; public examples can contain mistakes.\'}\n    (output/\'public-sources.json\').write_text(json.dumps(manifest,indent=2),encoding=\'utf-8\')\n    print(json.dumps(manifest),flush=True)\n    return manifest\n\nif __name__==\'__main__\':\n    parser=argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\'--output\',default=str(Path(__file__).resolve().parent/\'data\'))\n    parser.add_argument(\'--everyday\',type=int,default=2260); parser.add_argument(\'--magpie\',type=int,default=5000)\n    args=parser.parse_args()\n    try: download(args.output,args.everyday,args.magpie)\n    except KeyboardInterrupt: sys.exit(\'Stopped; downloaded pages are cached. Rerun to continue.\')\n    except Exception as error: sys.exit(\'Public download failed (\'+type(error).__name__+\'). Cached pages are preserved; rerun to retry.\')\n', 'model/train_public.py': '"""Larger from-scratch Nebula training on cached public data, on CPU or CUDA."""\nimport argparse\nimport json\nimport os\nfrom pathlib import Path\nimport sys\nfrom types import SimpleNamespace\n\nroot=Path(__file__).resolve().parent\nruntime=root.parents[3]/\'work/nebula-python-deps\'\nif runtime.joinpath(\'torch\').is_dir(): sys.path.insert(0,str(runtime))\nimport torch\nfrom nebula import config_for_preset,load,Nebula\nfrom dataflow import prepare,read_jsonl\nfrom train import train\nfrom public_data import download\n\ndef main():\n    parser=argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\'--download\',action=\'store_true\')\n    parser.add_argument(\'--preset\',choices=[\'cpu-medium\',\'cpu-large\',\'gpu\'],default=\'cpu-large\')\n    parser.add_argument(\'--stage\',choices=[\'language\',\'chat\'],default=\'language\')\n    parser.add_argument(\'--steps\',type=int,default=2000)\n    parser.add_argument(\'--batch\',type=int,default=2)\n    parser.add_argument(\'--threads\',type=int,default=min(4,os.cpu_count() or 1))\n    parser.add_argument(\'--device\',choices=[\'auto\',\'cpu\',\'cuda\'],default=\'auto\')\n    parser.add_argument(\'--save-every\',type=int,default=200)\n    parser.add_argument(\'--max-validation\',type=int,default=128)\n    parser.add_argument(\'--patience\',type=int,default=5)\n    parser.add_argument(\'--lr\',type=float,default=.0001,help=\'Learning rate; reduce this if numerical errors occur\')\n    parser.add_argument(\'--resume\',help=\'Resume weights from a compatible checkpoint\')\n    parser.add_argument(\'--prepared-data\',help=\'Use an existing prepared JSONL dataset without rewriting its bytes\')\n    args=parser.parse_args()\n    if args.max_validation<1: parser.error(\'--max-validation must be positive\')\n    if args.prepared_data:\n        if args.download: parser.error(\'--download and --prepared-data cannot be combined\')\n        prepared=Path(args.prepared_data)\n        if not prepared.is_file(): parser.error(\'Prepared dataset was not found\')\n        count=len(read_jsonl(prepared))\n    else:\n        data=root/\'data/public-conversations.jsonl\'\n        if args.download: download(root/\'data\')\n        if not data.exists(): parser.error(\'Download data first: python model/public_data.py\')\n        prepared=root/\'data/public-approved.jsonl\'\n        count=prepare([data,root/\'seed.jsonl\'],prepared)\n    config=config_for_preset(args.preset)\n    output=root/f\'checkpoints/nebula-{args.preset}-{args.stage}.pt\'\n    resume=Path(args.resume) if args.resume else output if output.exists() else None\n    if args.stage==\'chat\' and resume is None:\n        language=root/f\'checkpoints/nebula-{args.preset}-language.best.pt\'\n        if not language.exists(): parser.error(\'Run the language stage first, or explicitly provide --resume\')\n        resume=language\n    if resume:\n        previous,_=load(resume)\n        if previous.config!=config: parser.error(\'Checkpoint size does not match preset; choose a new output preset or compatible checkpoint\')\n        parameters=sum(p.numel() for p in previous.parameters()); del previous\n    else:\n        probe=Nebula(config); parameters=sum(p.numel() for p in probe.parameters()); del probe\n    print(json.dumps({\'parameters\':parameters,\'contextBytes\':config.context,\'originalConversations\':count,\'stage\':args.stage,\'requestedDevice\':args.device,\'cudaAvailable\':torch.cuda.is_available(),\'resumeWeights\':str(resume) if resume else None,\'note\':\'Experimental from-scratch model; this run does not update the live website.\'}),flush=True)\n    train(SimpleNamespace(data=prepared,output=output,snapshot=None,resume=resume,preset=args.preset,steps=args.steps,batch=args.batch,threads=args.threads,seed=42,lr=args.lr,continuous=False,save_every=args.save_every,patience=args.patience,device=args.device,amp=True,objective=\'assistant\' if args.stage==\'chat\' else \'language\',grouped_split=True,bucketed=True,max_validation=args.max_validation))\n\nif __name__==\'__main__\': main()\n', 'model/evaluate.py': '"""Inspect a local checkpoint without teacher calls or deployment."""\nimport argparse\nimport json\nimport sys\nfrom pathlib import Path\n\nruntime = Path(__file__).resolve().parents[4] / \'work/nebula-python-deps\'\nif runtime.joinpath(\'torch\').is_dir(): sys.path.insert(0, str(runtime))\nimport torch\nfrom nebula import load\nfrom rules import with_owner_rules\n\ndef main():\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\'--checkpoint\', default=str(Path(__file__).resolve().parent/\'checkpoints/nebula-continuous.pt\'))\n    args = parser.parse_args()\n    torch.set_num_threads(2)\n    model, metadata = load(args.checkpoint)\n    print(json.dumps({\'checkpoint\': args.checkpoint, \'trainingSteps\': metadata.get(\'steps\'), \'validationLoss\': metadata.get(\'validationLoss\'), \'experimental\': True}), flush=True)\n    for prompt in [\'hi\', \'What is your name?\', \'What is 2 + 2?\', \'What is 7 + 8?\', \'Explain gravity simply.\', \'Can you help me write an email?\', \'My name is Sam. What is my name?\', \'Why is the sky blue?\', \'Tell me a short story.\', \'How do I boil an egg?\']:\n        torch.manual_seed(42)\n        reply = model.reply(with_owner_rules([{\'role\': \'user\', \'content\': prompt}]), max_tokens=120, temperature=.7)\n        print(json.dumps({\'prompt\': prompt, \'reply\': reply}, ensure_ascii=True), flush=True)\n\nif __name__ == \'__main__\': main()\n', 'model/export_node.py': '"""Export owned Nebula weights for the dependency-free Node inference runtime."""\nimport argparse\nimport base64\nimport json\nfrom dataclasses import asdict\nfrom pathlib import Path\nimport torch\nfrom nebula import load, pack_prompt\nfrom rules import with_owner_rules\n\ndef export(checkpoint, output, reference=None):\n    torch.set_num_threads(1)\n    model, metadata = load(checkpoint)\n    weights = {}\n    for name, tensor in model.state_dict().items():\n        if name == \'output.weight\': continue  # tied to token.weight\n        weights[name] = {\'shape\': list(tensor.shape), \'data\': base64.b64encode(tensor.detach().float().contiguous().numpy().astype(\'<f4\').tobytes()).decode()}\n    artifact = {\'format\': 1, \'config\': asdict(model.config), \'weights\': weights, \'metadata\': {\'experimental\': True, \'parameters\': sum(p.numel() for p in model.parameters()), \'trainingSteps\': metadata.get(\'steps\', 0)}}\n    path = Path(output); path.parent.mkdir(parents=True, exist_ok=True); temporary = path.with_suffix(\'.tmp\'); temporary.write_text(json.dumps(artifact, separators=(\',\', \':\')), encoding=\'utf-8\'); temporary.replace(path)\n    if reference:\n        messages = with_owner_rules([{\'role\': \'user\', \'content\': \'What is your name?\'}]); tokens = pack_prompt(messages, model.config.context)\n        with torch.no_grad(): logits = model(torch.tensor([tokens]))[0, -1].tolist()\n        Path(reference).write_text(json.dumps({\'messages\': messages, \'tokens\': tokens, \'logits\': logits}), encoding=\'utf-8\')\n    print(json.dumps({\'parameters\': artifact[\'metadata\'][\'parameters\'], \'bytes\': path.stat().st_size, \'experimental\': True}))\n\nif __name__ == \'__main__\':\n    parser = argparse.ArgumentParser(description=__doc__); parser.add_argument(\'--checkpoint\', required=True); parser.add_argument(\'--output\', required=True); parser.add_argument(\'--reference\'); args = parser.parse_args()\n    export(args.checkpoint, args.output, args.reference)\n', 'model/colab_transfer.py': '"""Verified, key-free checkpoint/data transfer. No ZIP archives are created."""\nimport hashlib\nimport json\nfrom pathlib import Path,PurePosixPath\nimport sys\nimport time\nimport zlib\nfrom datetime import datetime,timezone\n\nroot=Path(__file__).resolve().parent\nruntime=root.parents[3]/\'work/nebula-python-deps\'\nif runtime.joinpath(\'torch\').is_dir(): sys.path.insert(0,str(runtime))\nimport torch\n\nFORMAT=\'nebula-colab-transfer-2\'\nCHECKPOINTS=[\'nebula-cpu-large-language.pt\',\'nebula-cpu-large-language.best.pt\',\'nebula-cpu-large-chat.pt\',\'nebula-cpu-large-chat.best.pt\']\n\ndef stable_bytes(path):\n    for _ in range(4):\n        before=path.stat(); value=path.read_bytes(); after=path.stat()\n        if (before.st_size,before.st_mtime_ns,before.st_ino)==(after.st_size,after.st_mtime_ns,after.st_ino): return value\n        time.sleep(.2)\n    raise ValueError(\'A source file kept changing; retry after its checkpoint save finishes\')\n\ndef valid_checkpoint(path):\n    value=torch.load(path,map_location=\'cpu\',weights_only=True)\n    if value.get(\'format\')!=1 or not isinstance(value.get(\'state\'),dict): raise ValueError(\'Invalid model checkpoint\')\n    if any(not torch.isfinite(v).all() for v in value[\'state\'].values()): raise ValueError(\'Checkpoint contains non-finite weights\')\n    return value[\'config\'],value.get(\'metadata\',{})\n\ndef build(destination):\n    import io\n    torch.set_num_threads(1)\n    files={}; metadata={}\n    for name in CHECKPOINTS:\n        path=root/\'checkpoints\'/name\n        if not path.exists(): continue\n        raw=stable_bytes(path)\n        try: config,meta=valid_checkpoint(io.BytesIO(raw))\n        except ValueError: continue\n        relative=\'model/checkpoints/\'+name\n        files[relative]=raw\n        metadata[relative]={\'config\':config,\'steps\':meta.get(\'steps\',0),\'objective\':meta.get(\'objective\'),\'validationLoss\':meta.get(\'validationLoss\'),\'dataSha256\':meta.get(\'dataSha256\')}\n    if not metadata: raise ValueError(\'No healthy checkpoints found\')\n    # Copy only known model data; no .env, credentials, browser profiles, or Firebase keys.\n    names=[\'public-approved.jsonl\',\'public-sources.json\',\'approved.jsonl\',\'continuous.jsonl\',\'conversations-approved.jsonl\',\'conversations-seed.jsonl\',\'conversations-teacher-accepted.jsonl\',\'conversations-teacher-pending.jsonl\',\'gemini-accepted.jsonl\',\'gemini-pending.jsonl\']\n    for name in names:\n        path=root/\'data\'/name\n        if not path.exists(): continue\n        raw=stable_bytes(path)\n        if name.endswith(\'.jsonl\'):\n            rows=[json.loads(line) for line in raw.decode(\'utf-8\').splitlines() if line.strip()]\n            if any(row.get(\'source\',{}).get(\'kind\')==\'user\' for row in rows):\n                if name==\'public-approved.jsonl\': raise ValueError(\'Prepared public data unexpectedly contains account chat exports\')\n                continue\n        files[\'model/data/\'+name]=raw\n    data_path=\'model/data/public-approved.jsonl\'\n    if data_path not in files: raise ValueError(\'Prepared training data is missing\')\n    data_hash=hashlib.sha256(files[data_path]).hexdigest()\n    for name in [\'seed.jsonl\',\'DATA_SOURCES.md\']:\n        files[\'model/\'+name]=stable_bytes(root/name)\n    files[\'nebula-rules.json\']=stable_bytes(root.parent/\'nebula-rules.json\')\n    matching=[name for name,meta in metadata.items() if meta[\'dataSha256\']==data_hash]\n    if not matching: raise ValueError(\'Saved checkpoint does not match the prepared dataset\')\n    # Prefer the latest saved chat progress; keep best and language checkpoints too.\n    selected=next((name for name in [\'model/checkpoints/nebula-cpu-large-chat.pt\',\'model/checkpoints/nebula-cpu-large-chat.best.pt\',\'model/checkpoints/nebula-cpu-large-language.pt\',\'model/checkpoints/nebula-cpu-large-language.best.pt\'] if name in matching),None)\n    stamp=datetime.now(timezone.utc).strftime(\'%Y%m%dT%H%M%SZ\')\n    manifest={\'format\':FORMAT,\'snapshotId\':stamp,\'createdAtUTC\':datetime.now(timezone.utc).isoformat(),\'resumeCheckpoint\':selected,\'resumeStage\':\'chat\' if metadata[selected][\'objective\']==\'assistant\' else \'language\',\'preparedData\':data_path,\'dataSha256\':data_hash,\'checkpoints\':metadata,\'files\':{name:{\'bytes\':len(value),\'sha256\':hashlib.sha256(value).hexdigest()} for name,value in files.items()},\'resumeState\':\'Weights and data are preserved. Legacy checkpoints do not contain optimizer or sampler state.\',\'accountChatsIncluded\':False,\'apiKeysIncluded\':False}\n    destination=Path(destination); destination.mkdir(parents=True,exist_ok=True)\n    path=destination/f\'Nebula_Transfer_{stamp}.pt\'\n    temporary=path.with_suffix(\'.tmp\')\n    compressed={name:torch.frombuffer(bytearray(zlib.compress(value,6)),dtype=torch.uint8) for name,value in files.items()}\n    torch.save({\'format\':FORMAT,\'compression\':\'zlib\',\'manifest\':manifest,\'files\':compressed},temporary); temporary.replace(path)\n    (destination/\'transfer-manifest.json\').write_text(json.dumps(manifest,indent=2),encoding=\'utf-8\')\n    # Verify the serialized bundle, rather than trusting a successful file write.\n    verify(torch.load(path,map_location=\'cpu\',weights_only=True))\n    print(json.dumps({\'transfer\':str(path),\'megabytes\':round(path.stat().st_size/1e6,1),\'files\':len(files),\'resumeCheckpoint\':selected,\'steps\':metadata[selected][\'steps\'],\'stage\':manifest[\'resumeStage\']}),flush=True)\n    return path,manifest\n\ndef verify(payload):\n    if payload.get(\'format\')!=FORMAT or payload.get(\'manifest\',{}).get(\'format\')!=FORMAT: raise ValueError(\'Unsupported transfer format\')\n    manifest=payload[\'manifest\']; files=payload.get(\'files\',{})\n    if set(files)!=set(manifest[\'files\']): raise ValueError(\'Transfer file list mismatch\')\n    decoded={}\n    for name,encoded in files.items():\n        path=PurePosixPath(name)\n        if path.is_absolute() or \'..\' in path.parts or \'\\\\\' in name or \':\' in name: raise ValueError(\'Unsafe transfer path\')\n        allowed=(len(path.parts)==3 and path.parts[:2] in [(\'model\',\'data\'),(\'model\',\'checkpoints\')]) or name in [\'nebula-rules.json\',\'model/seed.jsonl\',\'model/DATA_SOURCES.md\']\n        if not allowed or not isinstance(encoded,torch.Tensor) or encoded.dtype!=torch.uint8 or encoded.ndim!=1: raise ValueError(\'Transfer contains unexpected content\')\n        expected=manifest[\'files\'][name]\n        decoder=zlib.decompressobj()\n        value=decoder.decompress(encoded.numpy().tobytes(),expected[\'bytes\']+1)\n        if not decoder.eof or decoder.unused_data: raise ValueError(\'Invalid compressed transfer entry\')\n        if len(value)!=expected[\'bytes\'] or hashlib.sha256(value).hexdigest()!=expected[\'sha256\']: raise ValueError(\'Transfer checksum mismatch\')\n        decoded[name]=value\n    if manifest[\'resumeCheckpoint\'] not in files or manifest[\'preparedData\'] not in files: raise ValueError(\'Resume inputs missing\')\n    payload[\'decodedFiles\']=decoded\n    return manifest\n\ndef restore(transfer,project,checkpoint_directory=None):\n    payload=torch.load(transfer,map_location=\'cpu\',weights_only=True)\n    manifest=verify(payload)\n    project=Path(project).resolve(); checkpoint_directory=Path(checkpoint_directory).resolve() if checkpoint_directory else project/\'model/checkpoints\'\n    project.mkdir(parents=True,exist_ok=True); checkpoint_directory.mkdir(parents=True,exist_ok=True)\n    preserved=[]\n    for name,value in payload[\'decodedFiles\'].items():\n        checkpoint=name.startswith(\'model/checkpoints/\')\n        target=checkpoint_directory/PurePosixPath(name).name if checkpoint else project.joinpath(*PurePosixPath(name).parts)\n        allowed_root=checkpoint_directory if checkpoint else project\n        if not target.resolve().is_relative_to(allowed_root): raise ValueError(\'Transfer target leaves its allowed directory\')\n        target.parent.mkdir(parents=True,exist_ok=True)\n        if target.exists():\n            if hashlib.sha256(target.read_bytes()).hexdigest()==manifest[\'files\'][name][\'sha256\']: continue\n            if checkpoint:\n                config,_=valid_checkpoint(target)\n                if config!=manifest[\'checkpoints\'][name][\'config\']: raise ValueError(\'Existing checkpoint architecture differs\')\n                preserved.append(name); continue\n            raise ValueError(\'Existing dataset or rules differ from the snapshot; refusing to overwrite\')\n        temporary=target.with_suffix(target.suffix+\'.restore-tmp\'); temporary.write_bytes(value); temporary.replace(target)\n    link=project/\'model/checkpoints\'\n    if checkpoint_directory!=link.resolve():\n        if link.exists(): raise ValueError(\'Checkpoint folder already exists; choose a fresh project directory\')\n        link.symlink_to(checkpoint_directory,target_is_directory=True)\n    return manifest,preserved\n\nif __name__==\'__main__\':\n    import argparse\n    parser=argparse.ArgumentParser(description=__doc__); parser.add_argument(\'--output\',required=True)\n    build(parser.parse_args().output)\n'}
